import itertools


def to_gray(n: int) -> int:
    """Binary to Gray code."""
    return n ^ (n >> 1)


def from_gray(g: int) -> int:
    """Gray code to binary via O(log n) XOR-shifts (no per-bit loop)."""
    result = g
    shift = 1
    while (g >> shift) or shift <= g.bit_length():
        if not (g >> shift):
            break
        result ^= g >> shift
        shift <<= 1
    return result


def gray_sequence(bits: int) -> list[int]:
    """Full reflected Gray code sequence of length 2**bits."""
    return [to_gray(i) for i in range(1 << bits)]
